<script setup lang="ts">
import { computed, ref } from 'vue';
import { usePage } from '@inertiajs/vue3';
import { formatPrice } from '@/data/products';

type OrderStatus = 'Chờ xử lý' | 'Đang giao' | 'Đã giao' | 'Trả hàng' | 'Hủy hàng';
type Order = {
    id: number; code: string; createdAt: string;
    customer: { name?: string; phone?: string; email?: string; address?: string; note?: string };
    vatInvoice: { requested: boolean; companyName?: string | null; taxCode?: string | null; address?: string | null; email?: string | null; rate?: number; amount?: number };
    items: Array<{ id: number; name: string; price: number; image: string; quantity: number }>;
    subtotal: number; shipping: number; totalShipping: number; total: number; payment: string; status: string;
};

const page = usePage();
const orders = ref<Order[]>(((page.props as any).orders ?? []) as Order[]);
const filter = ref<'all' | OrderStatus>('all');
const selected = ref<Order | null>(null);
const actionError = ref('');
const statusOptions: Array<{ key: 'all' | OrderStatus; label: string; icon: string }> = [
    { key: 'all', label: 'Tất cả', icon: 'bi-grid' },
    { key: 'Chờ xử lý', label: 'Chờ xử lý', icon: 'bi-hourglass-split' },
    { key: 'Đang giao', label: 'Đang giao', icon: 'bi-truck' },
    { key: 'Đã giao', label: 'Đã giao', icon: 'bi-check2-circle' },
    { key: 'Trả hàng', label: 'Trả hàng', icon: 'bi-arrow-return-left' },
    { key: 'Hủy hàng', label: 'Hủy hàng', icon: 'bi-x-circle' },
];
const statusMeta: Record<OrderStatus, { icon: string; className: string; description: string }> = {
    'Chờ xử lý': { icon: 'bi-hourglass-split', className: 'pending', description: 'TechStore đang tiếp nhận đơn hàng.' },
    'Đang giao': { icon: 'bi-truck', className: 'shipping', description: 'Đơn hàng đang được vận chuyển.' },
    'Đã giao': { icon: 'bi-check-circle-fill', className: 'delivered', description: 'Đơn hàng đã giao thành công.' },
    'Trả hàng': { icon: 'bi-arrow-return-left', className: 'returned', description: 'Đơn hàng đang ở trạng thái trả hàng.' },
    'Hủy hàng': { icon: 'bi-x-circle-fill', className: 'cancelled', description: 'Đơn hàng đã được hủy.' },
};
const fallbackStatusMeta = { icon: 'bi-question-circle', className: 'pending', description: 'Trạng thái đơn hàng.' };
const normalizeStatus = (status: string): OrderStatus | null => (Object.prototype.hasOwnProperty.call(statusMeta, status) ? status as OrderStatus : null);
const getStatusMeta = (status: string) => {
    const normalized = normalizeStatus(status);
    return normalized ? statusMeta[normalized] : fallbackStatusMeta;
};
const filteredOrders = computed(() => filter.value === 'all' ? orders.value : orders.value.filter((order) => order.status === filter.value));
const activeCount = computed(() => orders.value.filter((order) => ['Chờ xử lý', 'Đang giao'].includes(order.status)).length);
const deliveredCount = computed(() => orders.value.filter((order) => order.status === 'Đã giao').length);
const totalSpent = computed(() => orders.value.filter((order) => order.status !== 'Hủy hàng').reduce((sum, order) => sum + Number(order.total), 0));
const currentUser = computed(() => ((page.props as any).auth?.user ?? null) as any);
const paymentLabel = (payment: string) => payment === 'paypal-sandbox' ? 'PayPal Sandbox' : payment === 'paypal-demo' ? 'PayPal mô phỏng' : 'Thanh toán khi nhận hàng';
const formatDate = (value: string) => new Intl.DateTimeFormat('vi-VN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value));
const statusClass = (status: string) => getStatusMeta(status).className;
function openOrder(order: Order) { selected.value = order; actionError.value = ''; }
function closeOrder() { selected.value = null; }
async function cancelOrder(order: Order) {
    if (order.status !== 'Chờ xử lý' || !window.confirm(`Hủy đơn hàng ${order.code}?`)) return;
    try {
        const token = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content ?? '';
        const response = await fetch(`/orders/${order.id}/cancel`, { method: 'PATCH', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': token } });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.order) throw new Error(data.message ?? 'Không thể hủy đơn hàng.');
        const index = orders.value.findIndex((item) => item.id === order.id);
        if (index >= 0) orders.value[index] = data.order;
        if (selected.value?.id === order.id) selected.value = data.order;
    } catch (error) {
        actionError.value = error instanceof Error ? error.message : 'Không thể hủy đơn hàng.';
    }
}
</script>
<template>
    <section class="db-orders">
        <header class="db-orders-head"><div class="db-title"><span><i class="bi bi-bag-check" /></span><div><small>TECHSTORE · TÀI KHOẢN</small><h2>Đơn hàng</h2><p>Lịch sử mua hàng, trạng thái giao nhận và hóa đơn.</p></div></div><div class="db-count"><i class="bi bi-receipt" /><strong>{{ orders.length }}</strong><span>đơn hàng</span></div></header>
        <div v-if="actionError" class="db-error"><i class="bi bi-exclamation-circle" />{{ actionError }}</div>
        <div class="db-stats"><article><span class="blue"><i class="bi bi-receipt-cutoff" /></span><div><small>Tổng đơn hàng</small><strong>{{ orders.length }}</strong><em>Tất cả đơn đã tạo</em></div></article><article><span class="orange"><i class="bi bi-truck" /></span><div><small>Đang xử lý</small><strong>{{ activeCount }}</strong><em>Chờ xử lý hoặc đang giao</em></div></article><article><span class="green"><i class="bi bi-check2-circle" /></span><div><small>Đã giao</small><strong>{{ deliveredCount }}</strong><em>Giao thành công</em></div></article><article><span class="purple"><i class="bi bi-cash-stack" /></span><div><small>Giá trị mua hàng</small><strong>{{ formatPrice(totalSpent) }}</strong><em>Không tính đơn đã hủy</em></div></article></div>
        <section class="db-history"><header><div><h3>Lịch sử mua hàng</h3><p>Dữ liệu được nạp trực tiếp từ cơ sở dữ liệu theo tài khoản đang đăng nhập.</p></div><span><i class="bi bi-database-check" /> Cơ sở dữ liệu</span></header>
            <nav class="db-tabs"><button v-for="item in statusOptions" :key="item.key" type="button" :class="{ active: filter === item.key }" @click="filter = item.key"><i :class="['bi', item.icon]" />{{ item.label }}<b v-if="item.key !== 'all'">{{ orders.filter((order) => order.status === item.key).length }}</b></button></nav>
            <div v-if="filteredOrders.length" class="db-list"><article v-for="order in filteredOrders" :key="order.code" class="db-card"><header><div class="db-order-title"><span><i class="bi bi-receipt" /></span><div><strong>#{{ order.code }}</strong><small>{{ formatDate(order.createdAt) }}</small></div></div><span :class="['db-status', statusClass(order.status)]"><i :class="['bi', getStatusMeta(order.status).icon]" />{{ order.status }}</span></header><div class="db-card-body"><div class="db-thumbs"><div v-for="item in order.items.slice(0, 4)" :key="`${order.id}-${item.id}`" class="db-thumb"><img :src="item.image" :alt="item.name" /><b v-if="item.quantity > 1">×{{ item.quantity }}</b></div><div v-if="order.items.length > 4" class="db-more">+{{ order.items.length - 4 }}</div></div><div class="db-summary"><span>{{ order.items.reduce((sum, item) => sum + item.quantity, 0) }} sản phẩm · {{ paymentLabel(order.payment) }}</span><strong>{{ formatPrice(order.total) }}</strong><em>{{ getStatusMeta(order.status).description }}</em></div></div><footer><span><i class="bi bi-file-earmark-text" /> {{ order.vatInvoice.requested ? 'Có yêu cầu hóa đơn VAT' : 'Hóa đơn bán hàng' }}</span><div><button type="button" @click="openOrder(order)"><i class="bi bi-eye" /> Chi tiết</button><button v-if="order.status === 'Chờ xử lý'" type="button" class="danger" @click="cancelOrder(order)"><i class="bi bi-x-lg" /> Hủy hàng</button></div></footer></article></div>
            <div v-else class="db-empty"><div><i class="bi bi-bag-x" /></div><h3>Chưa có đơn hàng</h3><p>Tài khoản <strong>{{ currentUser?.email || currentUser?.name || 'hiện tại' }}</strong> chưa có đơn hàng phù hợp với trạng thái đã chọn.</p></div>
        </section>
        <Teleport to="body"><div v-if="selected" class="db-overlay" @click.self="closeOrder"><section class="db-modal"><header><div><small>CHI TIẾT ĐƠN HÀNG</small><h2>{{ selected.code }}</h2><span>{{ formatDate(selected.createdAt) }}</span></div><button type="button" @click="closeOrder"><i class="bi bi-x-lg" /></button></header><div class="db-modal-body"><div class="db-detail-status"><span :class="['db-status', statusClass(selected.status)]"><i :class="['bi', getStatusMeta(selected.status).icon]" />{{ selected.status }}</span><strong>{{ formatPrice(selected.total) }}</strong></div><section><h3><i class="bi bi-person-vcard" /> Thông tin khách hàng</h3><div class="db-info-grid"><div><small>Họ và tên</small><strong>{{ selected.customer?.name || '—' }}</strong></div><div><small>Số điện thoại</small><strong>{{ selected.customer?.phone || '—' }}</strong></div><div><small>Email</small><strong>{{ selected.customer?.email || currentUser?.email || '—' }}</strong></div><div class="full"><small>Địa chỉ nhận hàng</small><strong>{{ selected.customer?.address || '—' }}</strong></div><div v-if="selected.customer?.note" class="full"><small>Ghi chú</small><strong>{{ selected.customer.note }}</strong></div></div></section><section><h3><i class="bi bi-box-seam" /> Sản phẩm</h3><div class="db-items"><div v-for="item in selected.items" :key="`${selected.id}-${item.id}`"><img :src="item.image" :alt="item.name" /><span><strong>{{ item.name }}</strong><small>{{ item.quantity }} × {{ formatPrice(item.price) }}</small></span><b>{{ formatPrice(item.price * item.quantity) }}</b></div></div></section><section><h3><i class="bi bi-receipt-cutoff" /> Hóa đơn & thanh toán</h3><div class="db-info-list"><div><span>Thanh toán</span><strong>{{ paymentLabel(selected.payment) }}</strong></div><div><span>Tạm tính</span><strong>{{ formatPrice(selected.subtotal) }}</strong></div><div><span>Phí vận chuyển</span><strong>{{ formatPrice(selected.totalShipping) }}</strong></div><div v-if="selected.vatInvoice.requested"><span>Đơn vị xuất VAT</span><strong>{{ selected.vatInvoice.companyName || '—' }}</strong></div><div v-if="selected.vatInvoice.requested"><span>Mã số thuế</span><strong>{{ selected.vatInvoice.taxCode || '—' }}</strong></div><div v-if="selected.vatInvoice.requested"><span>Địa chỉ VAT</span><strong>{{ selected.vatInvoice.address || '—' }}</strong></div><div class="grand"><span>Tổng thanh toán</span><strong>{{ formatPrice(selected.total) }}</strong></div></div></section></div><footer><button type="button" class="close" @click="closeOrder">Đóng</button><a v-if="selected.vatInvoice.requested && selected.status === 'Đã duyệt'" :href="`/orders/${selected.id}/vat-invoice`" target="_blank" class="vat"><i class="bi bi-file-earmark-pdf" /> Tải hóa đơn VAT</a><button v-if="selected.status === 'Chờ xử lý'" type="button" class="cancel" @click="cancelOrder(selected)"><i class="bi bi-x-lg" /> Hủy đơn</button></footer></section></div></Teleport>
    </section>
</template>
<style scoped>
